// The node's request and response bodies, as the Rust code declares them: what the HTTP adapter
// checks the application's types against. Generated by `cargo test` from src/api/dto/typescript.rs;
// don't edit it by hand.

export type StatusResponse = { height: number, tip: string, 
/**
 * A string, since it can outgrow a JSON number.
 */
weight: string, 
/**
 * Transactions waiting in the mempool.
 */
pending: number, };

export type ValidityResponse = { valid: boolean, 
/**
 * Which block first breaks a rule, and how. `null` while the chain is valid.
 */
problem: string | null, length: number, 
/**
 * Total work or stake behind the chain. A string, since it can outgrow a JSON number.
 */
weight: string, };

export type ReplaceResponse = { 
/**
 * Whether the offered blocks were adopted.
 */
replaced: boolean, 
/**
 * This node's chain length afterwards.
 */
length: number, 
/**
 * The offered blocks build on one this node doesn't have: send more from further back.
 */
missing_parent: boolean, };

export type MineRequest = { miner: string, };

export type ForgeRequest = { 
/**
 * The validator's key, which signs the block. Only for local experiments.
 */
secret_key: string, };

export type ProposalRequest = { 
/**
 * The address that will sign the block.
 */
validator: string, 
/**
 * The next link of the validator's reveal chain. Leave it out while anyone may forge.
 */
reveal?: string | null, };

export type ConsensusResponse = { 
/**
 * `proof_of_work` or `proof_of_stake`.
 */
kind: "proof_of_work" | "proof_of_stake", 
/**
 * Proof of work only.
 */
difficulty: number | null, reward: number, 
/**
 * The most transfers a block may hold. `null` means no limit.
 */
max_block_transfers: number | null, 
/**
 * Proof of stake only: who must forge the next block. `null` means anyone may.
 */
next_validator: string | null, stakes: Array<StakeEntry>, total_stake: number, 
/**
 * Proof of stake only: the randomness the next validator is drawn from.
 */
beacon: string | null, 
/**
 * Proof of work only: the hashes the next block should take to find, on average. A string,
 * since it can outgrow a JSON number.
 */
work: string | null, 
/**
 * Proof of work with retargeting: the pace the difficulty aims for.
 */
target_block_secs: number | null, 
/**
 * Proof of work with retargeting: blocks between adjustments.
 */
retarget_interval: number | null, 
/**
 * Proof of work with retargeting: the next height whose work is adjusted.
 */
next_retarget: number | null, };

export type StakeEntry = { address: string, amount: number, };

export type SignRequest = { secret_key: string, to: string, amount: number, 
/**
 * Defaults to the sender's next nonce.
 */
nonce?: number | null, 
/**
 * Optional tip for whoever adds the block.
 */
fee?: number, 
/**
 * For a first stake. Worked out from `secret_key` when left out.
 */
commitment?: string | null, };

/**
 * A transaction and where it is.
 */
export type TransactionResponse = { transaction: Transaction, 
/**
 * `confirmed` or `pending`.
 */
status: "confirmed" | "pending", 
/**
 * The block holding it. `null` while it's pending.
 */
block: PlacementResponse | null, };

export type PlacementResponse = { height: number, hash: string, 
/**
 * Its place among the block's transactions. 0 is the block reward.
 */
position: number, timestamp: string, 
/**
 * Blocks on top of it, counting its own.
 */
confirmations: number, };

/**
 * Evidence that a confirmed transaction is in its block. To check it: hash `transaction` into
 * `leaf`, combine it with each step's hash on the step's side up to `header.merkle_root`, and
 * check that `header.hash` is the hash of the header and belongs to a chain you trust.
 */
export type ProofResponse = { transaction: Transaction, leaf: string, proof: Array<Step>, header: BlockHeader, 
/**
 * Blocks on top of it, counting its own.
 */
confirmations: number, };

/**
 * What fee to pay: `fee` is sure to win a place in the next block, if nothing else arrives
 * first; `recent` is what the last few blocks took, newest first.
 */
export type FeesResponse = { fee: number, 
/**
 * Places left in the next block. While there are any, no fee is needed.
 */
room: number | null, 
/**
 * The most transfers a block may hold. `null` means no limit.
 */
capacity: number | null, waiting: number, recent: Array<BlockFeesEntry>, };

export type BlockFeesEntry = { height: number, transfers: number, full: boolean, lowest_fee: number | null, };

export type WalletResponse = { address: string, 
/**
 * Only for local experiments: a real wallet never sends its key over the wire.
 */
secret_key: string, };

export type BalanceResponse = { address: string, balance: number, staked: number, next_nonce: number, 
/**
 * The epoch this address's next commitment would be, and so the one after its active one.
 */
next_epoch: number, 
/**
 * Reveals left on its active commitment, if it has one.
 */
reveals_left: number | null, 
/**
 * If its next stake must carry a commitment, the epoch to make it for.
 */
commitment_due: number | null, };

export type PeerRequest = { url: string, };

export type PeerResponse = { url: string, 
/**
 * The peer's chain length when last reached.
 */
height: number | null, last_seen: string | null, 
/**
 * Why the last attempt to reach it failed, if it did.
 */
error: string | null, };

export type AddPeerResponse = { url: string, added: boolean, };

export type SyncResponse = { adopted_from: string | null, reached: number, length: number, };

export type NodeResponse = { version: string, 
/**
 * The git commit the node was built from. `-dirty` means uncommitted changes.
 */
commit: string, started_at: string, };

export type ErrorResponse = { message: string, };

export type Block = { index: number, timestamp: string, prev_hash: string, transactions: Array<Transaction>, 
/**
 * The root of the Merkle tree over `transactions`. The hash covers it instead of the
 * transactions, so a transaction can be proven to be in the block from its header alone.
 */
merkle_root: string, 
/**
 * Proof-of-work counter. Always 0 under proof of stake.
 */
nonce: number, hash: string, 
/**
 * Proof of stake only: who forged the block. Left out of proof-of-work blocks entirely, so
 * their JSON and hashes are unchanged.
 */
validator?: string, 
/**
 * Proof of stake only: the next link of the validator's reveal chain, mixed into the beacon
 * that picks who forges next. Absent while nothing is staked.
 */
reveal?: string, 
/**
 * Proof of stake only: the validator's signature over `hash`.
 */
signature?: string, };

export type BlockHeader = { index: number, timestamp: string, prev_hash: string, merkle_root: string, nonce: number, hash: string, validator?: string, reveal?: string, signature?: string, };

export type Transaction = { from: string, to: string, amount: number, 
/**
 * How many transactions the sender has made before this one. Stops replays.
 */
nonce: number, 
/**
 * Hex-encoded ed25519 signature over `signing_payload()`. Empty for coinbase.
 */
signature: string, 
/**
 * Optional tip for whoever adds the block, paid on top of `amount`. Left out when zero, so
 * transactions without one keep their original JSON and signature.
 */
fee?: number, 
/**
 * Stakes only: the end of the staker's reveal hash chain, needed the first time they stake
 * (see `randao`). Left out otherwise.
 */
commitment?: string, };

/**
 * One level of a proof: the hash to combine with, and on which side.
 */
export type Step = { hash: string, side: Side, };

/**
 * Which side of the hash so far a proof's sibling sits on.
 */
export type Side = "left" | "right";
